def is_valid_age(text):
    try:
        age = int(text)
    except ValueError:
        return False
    return 0 <= age <= 150


values = input().split()
ages = [int(v) for v in values if is_valid_age(v)]
invalid = len(values) - len(ages)

print(f"유효: {len(ages)}개, 무효: {invalid}개")
if ages:
    print(f"평균 나이: {sum(ages) / len(ages):.1f}")
else:
    print("평균 나이: 없음")
